class Solution {
public:
    int maxRemoval(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        int m = queries.size();

        sort(queries.begin(), queries.end());

        vector<int> diff(n + 1, 0);
        priority_queue<int> pq;
        int used = 0;
        int qIdx = 0;
        int coverage = 0;

        for (int i = 0; i < n; i++) {
            while (qIdx < m && queries[qIdx][0] == i) {
                pq.push(queries[qIdx][1]);
                qIdx++;
            }

            coverage += diff[i];

            while (!pq.empty() && pq.top() < i) {
                pq.pop();
            }

            while (coverage < nums[i]) {
                if (pq.empty()) return -1;
                int r = pq.top();
                pq.pop();
                diff[i]++;
                diff[r + 1]--;
                coverage++;
                used++;
            }
        }

        return m - used;
    }
};
